{"op":"add","path":"/root","value":"trip-composer"}
{"op":"add","path":"/elements/trip-composer","value":{"type":"Composer","props":{"headline":"Plan your trip within budget","lede":"Choose your dates, set a spending limit, and make room for what matters.","columns":"1","runLabel":"Plan my trip","notes":["Estimated costs by category and in total.","Practical notes for getting around and staying comfortable."]},"children":["trip-grid","anything-else"],"on":{"press":[{"action":"validateForm"},{"action":"run"}]}}}
